const formatRating = (rating: number) => {
  const fullStars = Math.floor(rating);
  const halfStar = rating % 1 >= 0.5 ? "½" : "";
  return `${"★".repeat(fullStars)}${halfStar}${"☆".repeat(5 - fullStars - (halfStar ? 1 : 0))}`;
};

